export function FormElement({
  heading = "{{heading}}",
  buttonLabel = "{{buttonLabel}}",
  accent = "{{accent}}",
  required = {{required}},
}) {
  return (
    <form onSubmit={(e) => e.preventDefault()} style={{ width: 280, boxSizing: "border-box", font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, border: "1.5px solid #24143020", display: "flex", flexDirection: "column", gap: 8 }}>
      <h3 style={{ margin: "0 0 4px", fontSize: 17, fontWeight: 700 }}>{heading}</h3>
      <label htmlFor="frm-r-email" style={{ fontSize: 12, fontWeight: 600, color: "#241430aa" }}>Email address</label>
      <input id="frm-r-email" name="email" type="email" placeholder="you@example.com" required={required}
        style={{ font: "14px system-ui, sans-serif", padding: "9px 11px", borderRadius: 7, border: "1.5px solid #24143035", borderLeft: required ? `3px solid ${accent}` : "1.5px solid #24143035" }} />
      <button type="submit" style={{ marginTop: 6, font: "700 14px system-ui, sans-serif", padding: 10, borderRadius: 8, border: "none", background: accent, color: "#241430", cursor: "pointer" }}>{buttonLabel}</button>
    </form>
  );
}
